<?php
define('APP_INIT',true);
require_once __DIR__.'/config/app.php';
$db=Database::getConnection();
$plans=$db->query("SELECT * FROM subscription_plans WHERE status='active' ORDER BY display_order,id")->fetchAll();
$error=''; $success='';
if ($_SERVER['REQUEST_METHOD']==='POST') {
    $name=trim($_POST['owner_name']??''); $business=trim($_POST['business_name']??''); $mobile=trim($_POST['mobile']??''); $email=trim($_POST['email']??'');
    $username=strtolower(trim($_POST['username']??'')); $pass=$_POST['password']??''; $confirm=$_POST['confirm_password']??''; $planId=(int)($_POST['plan_id']??0);
    $method=$_POST['payment_method']??'bKash'; $billing=$_POST['billing_period']??'monthly'; $reference=trim($_POST['reference']??''); $receiptPath=null;
    if (!verifyCsrfToken($_POST['csrf_token']??'')) $error='Invalid request token. Please refresh and try again.';
    elseif ($name==='' || $business==='' || !filter_var($email,FILTER_VALIDATE_EMAIL) || !preg_match('/^[a-z0-9_.-]{3,50}$/',$username) || strlen($pass)<8 || $pass!==$confirm || !$planId || $reference==='') $error='Complete all required fields. Transaction ID and a matching 8-character password are required.';
    elseif (!in_array($billing,['monthly','yearly'],true)) $error='Choose a valid billing cycle.';
    else {
        try {
            if (!empty($_FILES['payment_receipt']) && $_FILES['payment_receipt']['error']!==UPLOAD_ERR_NO_FILE) {
                $file=$_FILES['payment_receipt'];
                if ($file['error']!==UPLOAD_ERR_OK || $file['size']>5*1024*1024) throw new Exception('Receipt upload failed. Use a PNG, JPG, or WEBP image up to 5 MB.');
                $info=@getimagesize($file['tmp_name']); $types=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
                if (!$info || !isset($types[$info['mime']])) throw new Exception('Receipt must be a valid PNG, JPG, or WEBP image.');
                $dir=PRIVATE_STORAGE_PATH.'/payment_receipts';
                if (!is_dir($dir) && !mkdir($dir,0755,true) && !is_dir($dir)) throw new Exception('Payment receipt storage is unavailable.');
                $filename=bin2hex(random_bytes(18)).'.'.$types[$info['mime']];
                if (!move_uploaded_file($file['tmp_name'],$dir.'/'.$filename)) throw new Exception('Could not save the payment receipt.');
                $receiptPath='payment_receipts/'.$filename;
            }
            $db->beginTransaction();
            $p=$db->prepare("SELECT * FROM subscription_plans WHERE id=:id AND status='active'"); $p->execute([':id'=>$planId]); $plan=$p->fetch();
            if (!$plan) throw new Exception('Selected plan is unavailable.');
            $u=$db->prepare('SELECT id FROM users WHERE username=:u'); $u->execute([':u'=>$username]); if($u->fetchColumn()) throw new Exception('That username is already used.');
            $slug=strtolower(trim(preg_replace('/[^a-z0-9]+/i','-',$business),'-')); $check=$db->prepare('SELECT id FROM tenants WHERE slug=:slug'); $check->execute([':slug'=>$slug]); if($check->fetchColumn()) $slug.='-'.time();
            $t=$db->prepare('INSERT INTO tenants(name,slug,owner_name,owner_phone,owner_email,status) VALUES(:name,:slug,:owner,:phone,:email,"trial")'); $t->execute([':name'=>$business,':slug'=>$slug,':owner'=>$name,':phone'=>$mobile,':email'=>$email]); $tenant=(int)$db->lastInsertId();
            $setting=$db->prepare('INSERT INTO tenant_settings(tenant_id,setting_key,setting_value) VALUES(:tenant,:key,:value) ON DUPLICATE KEY UPDATE setting_value=:value2');
            foreach(['business_name'=>$business,'business_mobile'=>$mobile,'business_email'=>$email] as $key=>$value){$setting->execute([':tenant'=>$tenant,':key'=>$key,':value'=>$value,':value2'=>$value]);}
            $role=$db->query("SELECT id FROM roles WHERE slug='admin' LIMIT 1")->fetchColumn();
            $newUser=$db->prepare('INSERT INTO users(tenant_id,role_id,name,username,email,phone,password,status) VALUES(:tenant,:role,:name,:username,:email,:phone,:password,"active")');
            $newUser->execute([':tenant'=>$tenant,':role'=>$role,':name'=>$name,':username'=>$username,':email'=>$email,':phone'=>$mobile,':password'=>password_hash($pass,PASSWORD_DEFAULT)]);
            $sub=$db->prepare('INSERT INTO tenant_subscriptions(tenant_id,plan_id,status,starts_at,ends_at) VALUES(:tenant,:plan,"trial",CURDATE(),DATE_ADD(CURDATE(),INTERVAL :days DAY))'); $sub->bindValue(':tenant',$tenant); $sub->bindValue(':plan',$planId); $sub->bindValue(':days',(int)$plan['trial_days'],PDO::PARAM_INT); $sub->execute(); $subscription=(int)$db->lastInsertId();
            $amount=$billing==='yearly'?(float)$plan['yearly_price']:(float)$plan['price'];
            $pay=$db->prepare('INSERT INTO subscription_payments(tenant_id,subscription_id,amount,payment_method,billing_period,gateway,transaction_reference,attachment_path,payment_date,status) VALUES(:tenant,:subscription,:amount,:method,:billing,"manual",:reference,:receipt,CURDATE(),"pending")');
            $pay->execute([':tenant'=>$tenant,':subscription'=>$subscription,':amount'=>$amount,':method'=>in_array($method,['bKash','Nagad','Bank','Cash','Other'])?$method:'Other',':billing'=>$billing,':reference'=>$reference,':receipt'=>$receiptPath]);
            $db->commit(); $success='Registration submitted. Your trial is active and your payment is waiting for platform review.';
        } catch(Throwable $e) { if($db->inTransaction())$db->rollBack(); if($receiptPath && is_file(PRIVATE_STORAGE_PATH.'/'.$receiptPath)) @unlink(PRIVATE_STORAGE_PATH.'/'.$receiptPath); $error='Registration failed: '.$e->getMessage(); }
    }
}
?><!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Start Free Trial | Dealership SaaS</title><link href="https://cdn.jsdelivr.net/npm/bootstrap@5.3.3/dist/css/bootstrap.min.css" rel="stylesheet"><style>body{min-height:100vh;background:radial-gradient(circle at 18% 12%,#4a1e88 0,transparent 30%),radial-gradient(circle at 85% 88%,#123b72 0,transparent 31%),#070912;color:#f7f8ff}.wrap{max-width:1000px}.reg-card{background:rgba(16,20,38,.92);border:1px solid rgba(180,150,255,.25);box-shadow:0 24px 80px rgba(0,0,0,.45);border-radius:24px}.eyebrow{color:#bda2ff}.form-label{color:#f5f6ff!important;font-weight:600}.form-control,.form-select{background:#fff!important;color:#111827!important;border:1px solid #c7c9d5!important;min-height:46px}.form-control::placeholder{color:#6b7280!important}.side{background:linear-gradient(145deg,#6d28d9,#27105e);border-radius:20px}.btn-violet{background:linear-gradient(90deg,#7c3aed,#a855f7);color:#fff;border:0;font-weight:700}.muted{color:#c4c8d8}</style></head><body><main class="container wrap py-5"><div class="row g-4 align-items-stretch"><div class="col-lg-5"><div class="side p-4 h-100"><a class="text-white text-decoration-none fw-bold" href="<?=BASE_URL?>">✦ Dealership SaaS</a><div class="mt-5"><p class="eyebrow fw-semibold">START YOUR TRIAL</p><h1 class="display-6 fw-bold">Bring every dealership operation together.</h1><p class="muted">Create an independent business workspace. Your business data stays isolated from every other tenant.</p><ul class="list-unstyled mt-4"><li class="mb-3">✓ Multiple companies & products</li><li class="mb-3">✓ Sales, purchase, stock & ledger</li><li class="mb-3">✓ Configurable commission engine</li><li>✓ Protected payment review</li></ul></div></div></div><div class="col-lg-7"><div class="reg-card p-4 p-md-5"><h2 class="fw-bold">Create your business account</h2><p class="muted">Enter your payment reference so the platform owner can review and activate your subscription.</p><?php if($error):?><div class="alert alert-danger"><?=htmlspecialchars($error)?></div><?php endif?><?php if($success):?><div class="alert alert-success"><?=htmlspecialchars($success)?> <a href="<?=BASE_URL?>/login.php">Login</a></div><?php else:?><form method="post" enctype="multipart/form-data"><?php echo csrfField()?><div class="row g-3"><div class="col-md-6"><label class="form-label">Owner name</label><input name="owner_name" required class="form-control" placeholder="Your full name"></div><div class="col-md-6"><label class="form-label">Business name</label><input name="business_name" required class="form-control" placeholder="e.g. Rahim Traders"></div><div class="col-md-6"><label class="form-label">Mobile</label><input name="mobile" required class="form-control" placeholder="01XXXXXXXXX"></div><div class="col-md-6"><label class="form-label">Email</label><input name="email" type="email" required class="form-control" placeholder="you@example.com"></div><div class="col-md-6"><label class="form-label">Username</label><input name="username" required class="form-control" placeholder="Choose a login username"></div><div class="col-md-6"><label class="form-label">Plan</label><select name="plan_id" class="form-select"><?php foreach($plans as $p):?><option value="<?=$p['id']?>" <?=((int)($_GET['plan']??0)===$p['id'])?'selected':''?>><?=htmlspecialchars($p['name'])?> — ৳<?=number_format($p['price'],0)?> / month</option><?php endforeach?></select></div><div class="col-md-6"><label class="form-label">Password</label><input name="password" type="password" minlength="8" required class="form-control" placeholder="Minimum 8 characters"></div><div class="col-md-6"><label class="form-label">Confirm password</label><input name="confirm_password" type="password" minlength="8" required class="form-control" placeholder="Repeat your password"></div><div class="col-md-6"><label class="form-label">Billing cycle</label><select name="billing_period" class="form-select"><option value="monthly">Monthly</option><option value="yearly">Yearly</option></select></div><div class="col-md-6"><label class="form-label">Payment method</label><select name="payment_method" class="form-select"><option>bKash</option><option>Nagad</option><option>Bank</option><option>Cash</option><option>Other</option></select></div><div class="col-md-6"><label class="form-label">Transaction ID / reference</label><input name="reference" required class="form-control" placeholder="Payment transaction ID"></div><div class="col-md-6"><label class="form-label">Payment receipt <span class="muted">optional, max 5 MB</span></label><input name="payment_receipt" type="file" accept="image/png,image/jpeg,image/webp" class="form-control"></div></div><button class="btn btn-violet w-100 mt-4 py-3">Create account & submit payment →</button></form><?php endif?><p class="muted small text-center mt-3 mb-0">Already have an account? <a class="text-white" href="<?=BASE_URL?>/login.php">Sign in</a></p></div></div></div></main></body></html>
